(function () {
  "use strict";

  var G = window.GEOSNAP;
  var payload = G.payload;
  var parameters = (payload.analysis && payload.analysis.parameters) || {};
  var online = payload.online || {};

  function parameter(name, unit) {
    return parameters[name] === undefined ? "the configured value" : parameters[name] + " " + unit;
  }
  var stopRadius = parameter("stop_radius_m", "m");
  var stopMinutes = parameter("stop_min_minutes", "minutes");
  var gapMinutes = parameter("gap_min_minutes", "minutes");
  var maxAccuracy = parameter("max_accuracy_m", "m");
  var implausibleSpeed = parameter("implausible_speed_kmh", "km/h");
  var encounterMinutes = parameter("encounter_max_minutes", "minutes");
  var encounterDistance = parameter("encounter_max_distance_m", "m");
  var jointMovementMinimum = parameter("encounter_joint_movement_min_m", "m");
  var matrixTolerance = parameter("matrix_tolerance_m", "m");
  var accuracyScaleFactor = G.accuracyScaleFactor;
  var staysSentence = payload.analysis
    ? "Places where the device lingered at least " + stopMinutes + " within " + stopRadius + " (circle = stop radius, label = duration), computed at generation time; the tooltip shows the looked-up address when Nominatim was used. A silence of at least " + gapMinutes + " between two analysed reports (within the accuracy limit) ends a stay: a stay never spans such a silence, even when reports beyond the accuracy limit fall into it."
    : "Places where the device lingered at least the configured minimum duration within the configured stop radius (circle = stop radius, label = duration), computed at generation time; the tooltip shows the looked-up address when Nominatim was used. A silence of at least the configured gap threshold between two analysed reports (within the accuracy limit) ends a stay.";

  var casePlaceBlock = (payload.analysis && payload.analysis.case_places) || {};
  // gap_threshold_minutes and unknown_accuracy_margin_m as used by the check at generation.
  var casePlaceGapMinutes = casePlaceBlock.gap_threshold_minutes === undefined ? gapMinutes : casePlaceBlock.gap_threshold_minutes + " minutes";
  var casePlaceMargin = casePlaceBlock.unknown_accuracy_margin_m === undefined ? maxAccuracy : casePlaceBlock.unknown_accuracy_margin_m + " m";

  // One sentence per layer of the Leaflet layer control (keys = overlay names as registered).
  var LAYER_HELP = {
    "Points": "Every extracted position as a dot in the colour of its source (ring and fill; with \"colour by time\" the fill runs from blue to red and the ring keeps the source colour). Hover for the source, the original record, both timestamps and the number of duplicate reports; records that carry a name and description (KML, GPX, CSV with those columns, Google) also show them. Records without an accuracy value (KML, GPX, and CSV or Google records that lack one) read \"Accuracy: not reported\". Click to highlight the previous and next point of the same source with distance, time difference and speed. Records without a timestamp (KML placemarks or GPX points without a time, GeoJSON features without a time property, CSV rows with an empty time cell or from a mapping without a time column, Google frequent places) sit in this layer as hollow rings in the source colour, with the tooltip row \"Timestamp: none in the record\" and no sequence number; the time filter, the time cursor and every time-based analysis (stays, gaps, movement, encounters, presence matrix, crystal ball, timeline) leave them out, while the browser exports include them with empty time fields.",
    "Accuracy circles": "One circle per point whose radius is the ± accuracy in metres reported in the source line; records without an accuracy value (KML, GPX, and CSV or Google records that lack one) get no circle.",
    "Route": "One line per source joining its positions in chronological order, in the source colour; positions of different sources are never joined.",
    "Heatmap": "Density of the shown positions with a timestamp; brighter means more reports nearby. A visual aid, not a measurement. Records without a timestamp are left out.",
    "Convex hull": "Per source, the smallest convex area that encloses its shown positions with a timestamp. Records without a timestamp are left out.",
    "Graticule": "Latitude/longitude grid with labels, so positions can be read without a base map.",
    "Movement classes": "Route segments of each source coloured by the speed between consecutive positions, computed at generation time from WGS84 geodesic distances: grey stationary (within the combined accuracy of both points, or below 1 km/h over less than " + gapMinutes + "), green walking (below 7 km/h), blue cycling (below 25 km/h), orange vehicle, red dashed implausible (" + implausibleSpeed + " or faster; for two records at the same instant: when even the lowest speed their interval allows reaches it), grey unknown (same instant otherwise, or a slow average across a silence of at least " + gapMinutes + ", which says nothing about standing still). Implausible and unknown steps do not count towards the distance of the report. The segment tooltip gives the speed interval (see Speed tool). Points with an accuracy above " + maxAccuracy + " are excluded from the analysis.",
    "Direction arrows": "An arrow at each segment midpoint pointing in the direction of travel.",
    "Sequence numbers": "The chronological index of each position within its source (1 = oldest), framed in the source colour.",
    "Stays": staysSentence,
    "Gaps": "Dashed lines in the source colour between consecutive dated records of one source at least " + gapMinutes + " apart, i.e. no record in between, also none beyond the accuracy limit; drawn from the analysis, so they stay even when the map omits the two points.",
    "Last known position": "Per source the newest analysable position (accuracy within " + maxAccuracy + "), labelled \"Last known · <source>\" in the source colour with its time and, when available, its looked-up address.",
    "Encounters": "Places where two sources reported within " + encounterMinutes + " and " + encounterDistance + " of each other, or within the combined accuracy of the two reports if that is larger, computed at generation time. Every accepted report takes part, whatever its accuracy, except records of an excluded positioning method (see Positioning method). The accuracies are uncertainty radii at the analysis level (see Accuracy level): " + (parameters.accuracy_confidence === "reported" ? "used as reported on this map, so two reports of ±1600 m coincide up to 3200 m apart" : (parameters.accuracy_confidence === undefined ? "at 95 % by default" : "at 95 % on this map") + ", so two reports of ±1600 m at 68 % or unknown level coincide up to about " + Math.round(3200 * accuracyScaleFactor / 10) * 10 + " m apart (as reported: 3200 m)") + "; an encounter whose reports never came within " + encounterDistance + " of each other coincided only through their accuracy and is classed within accuracy, not same place. The badge sits at the centre; its ring shows the colours of the two sources. The tooltip gives both sources, the local start and end, the duration, the smallest distance and the number of reports of each source. Clicking the badge draws both sources' reports inside the encounter window and a dashed line between the closest pair on this map; a click on the map clears it. Joint movement: an encounter of at least 5 minutes in which the reports of both sources stayed within the encounter distance (or their combined accuracy) and time while both moved: the path through the midpoints of the coinciding reports, and the participating reports of each source by themselves, each cover at least " + jointMovementMinimum + ". The path length is the length of the plausible steps: steps shorter than the encounter distance (or than the combined accuracy of the two reports, if larger) count as scatter and add nothing, and a step without elapsed time or at " + implausibleSpeed + " or faster is a position jump of the source data, or travel at that speed, such as a flight, and is excluded: its length is given as excluded length with the number of such steps (tooltip, timeline, CSV, report), and the line on the map is broken there. The speed limit is that of the movement classes, but those run on the positions within the accuracy limit, encounters on every accepted report of a method that is not excluded, so the two can differ. The displacement is the distance from the first to the last midpoint, jumps included. An encounter may span rest and movement; the class applies to the whole encounter. Every other encounter is classed same place, or within accuracy when its reports never came within the encounter distance of each other; a joint movement of that kind is marked (only within accuracy). A joint movement is drawn as a line through the midpoints (at most 200 vertices) in the colours of both sources instead of the badge. It describes the reports of two devices: it does not say that they were in the same vehicle, nor who carried them; reports of two devices on the same road, train or bus look the same.",
    "Case places": "Locations from the case file entered by the examiner, checked against every source at generation time: a label and a dashed circle with the entered radius (not a source colour). Hover for the verdict per shown source; click for the window, verdict, closest approach, visits and possible visits per source. A position marked \"geocoded, not verified by the examiner\" is the first answer of an address search. A case place without coordinates (not located) has no marker and was not checked; the timeline names it.",
    "Shared places": "Places where the stays of at least two sources lie together, computed at generation time; the ring shows the colours of the sources, the tooltip lists every visit and whether visits overlapped in time."
  };
  function layerHelp(name) {
    return LAYER_HELP[name] || "(no description)";
  }

  var fallbackHost = online.overpass_fallback_endpoint ? online.overpass_fallback_endpoint.replace(/^https:\/\//, "").split("/")[0] : "";
  // Discloses where a refused check from disk goes (online.overpass_fallback_endpoint).
  var fallbackSentence = fallbackHost
    ? "When that server refuses such a map, the same check is sent exactly once to the fallback " + fallbackHost +
      " (online.overpass_fallback_endpoint): the checked area then goes to that operator, and the status line names the server that answered."
    : "No fallback is configured (online.overpass_fallback_endpoint is empty), so its live checks fail with \"the Overpass server refused the request\".";

  var walkingMaxKmh = 7;
  var implausibleForSpeed = parameters.implausible_speed_kmh === undefined ? "the configured limit" : parameters.implausible_speed_kmh + " km/h";

  var TOOL_HELP = [
    ["Layer control", "Top right, one block per group: Records (points, accuracy circles, sequence numbers, heatmap, convex hull), Movement per source (route, direction arrows, movement classes, stays, gaps, last known position), Between sources (encounters, shared places), Case (case places, records without a timestamp per source) and Map (graticule). Direction arrows and movement classes belong to the route: they can only be on while Route is on, and switching Route off switches them off and remembers their state, so turning Route back on restores it. A layer whose records do not exist in this map stays in its place, greyed and switched off, and its tooltip says why. Every checkbox is reachable with the keyboard; the chevron in the title bar folds the control."],
    ["Control tooltips and unavailable controls", "Every button, checkbox, list, slider and layer row explains itself in a small box after " + G.CONTROL_TOOLTIP_DELAY_MS + " ms, on hover and on keyboard focus (Escape closes it). The tooltips of the points on the map are separate and appear at once. A control whose basis is missing is disabled and greyed but keeps its place, and its tooltip names the reason, for example \"needs timestamps on at least half of the records: 3 of 40 have one\". The basis is recomputed for the shown sources: hiding a source in the Sources window can switch a control off, showing it again brings it back. Gating changes only what can be used in this browser, never the recorded data."],
    ["Speed tool", "The toolbar button \"Speed\" switches on a selection mode: click two records of one source, in either order: the range runs from the earlier to the later in the recorded order, so choosing backwards gives the same range. It covers every analysed record of that source between the two ends, whatever the filters show, so its figures cannot change with the view. Distances are WGS84 geodesics (GeographicLib, Karney 2013). The panel gives the records in the range, the elapsed time with the time resolution of the source (the coarsest of 1 min, 1 s, 1 ms and 1 µs of which every timestamp of the source is a whole multiple), and as headline the minimum average speed: the straight line between the two ends, shortened by their two uncertainty radii (see Accuracy level), divided by the elapsed time plus the time resolution; beside it, in small type, the same minimum with the radii as reported when it differs. It is a lower bound that rests on the two end records only: the true path is at least as long as the straight line between the true end positions. The stepwise minimum sums the steps between consecutive records, each shortened likewise, and is shown apart with the number of records it depends on: it holds only if every one of them lies within its circle, which becomes unlikely for many records (with 68 % circles, 10 records all inside: about 2 %). The premise: the true positions lie within their uncertainty circles (at the 95 % level by default, see Accuracy level; not a guarantee) and every true instant within the time resolution; a record without an accuracy adds nothing to a minimum. Then the straight line and the path over the records with their averages (the path is an estimate, not a bound: position noise lengthens it and sparse records shorten it), the slowest and fastest step and the implausible steps. \"Exclude records\" switches a mode in which a click on a record strictly between the two ends excludes it (a red cross; a second click or Restore takes it back), for example a position outlier; the panel then shows every figure without the excluded records and with all records side by side. Every exclusion needs a reason (position outlier, implausible jump, duplicate position, or other, which needs a note); a note is optional for the others. On a thinned source the records between the ends are not all on the map: path and minimum come from the full list, the step figures only from the drawn records, and records cannot be excluded. \"Record calculation\" works only when the map was opened through GEOSnap (summary screen, key O) and every exclusion has a reason: GEOSnap reads the map file it serves, recomputes the range, refuses the record when the figures differ, and writes speed_ranges/speed_range_<n>_<stamp>.json and .html, chained in speed_ranges/records.jsonl, which GEOSnap --verify checks; note the SHA-256 of the last line in the case file. A click on a record of another source, on the same record again, on a record without a timestamp or on a record the accuracy limit or the positioning method filter of the run excluded from the analysis is refused with the reason; the order is the recorded one, never the file line. Clear forgets the choice, and leaving the mode clears it as well. Every point tooltip also carries \"Speed from previous record\": a small gauge from 0 to " + implausibleForSpeed + " in the colour of the movement class, the value below walking speed (" + walkingMaxKmh + " km/h) in m/s and above it in km/h, the step it comes from (\"38 m in 12 s\") and the speed interval under the same premise (bounds rounded outwards), followed by the interval with the radii as reported when it differs (\"as reported: 1.4–2.3\"), or \"none\" when a record reports no accuracy. The figures come from the analysis at generation time and are derived, not recorded."],
    ["Sources window (View → Sources)", "One row per source: show checkbox, colour, kind icon, name, kind, point count, first to last report, the input format, and \"accuracy not reported\" when no record of the source has an accuracy value or \"accuracy partly reported\" when only some have one (the legend notes the same per source). It opens by default when the map has two or more sources. Hidden sources disappear from the points, routes, heatmap, hull, movement classes, arrows, numbers, time cursor, neighbours, stays, gaps, last known positions, saved places, encounters, the case place verdicts and visits (popup and timeline rows; an open case place popup closes), the columns of the Matrix window, the briefing sections, the exports and the print; the filter line names the shown sources. All/None switch every source. The colour field recolours a source on this map at once. Show and colour are view choices in this browser and are not recorded; metadata.json keeps the colours of the run."],
    ["Time filter (From/To)", "Date, hour (00-23) and minute in the display zone, prefilled with the first and last report; every change applies at once and To includes the whole minute. Times are compared in UTC: in the hour repeated when clocks go back, From means the earlier occurrence and To the later one, so both are covered; a time in the hour skipped when clocks go forward means the next valid time. Where a wall-clock time occurs twice in the display zone, lists and tooltips add its UTC offset (e.g. 02:30 +02:00). Points, accuracy circles, route, heatmap, convex hull, movement classes, arrows, sequence numbers and the exports follow the filter; stays, gaps, the last known position and places were computed at generation and do not. Reset restores the full span and switches the time cursor off."],
    ["Accuracy filter", "Hides positions whose ± accuracy is above the slider value on the map only; analysis.json is unaffected."],
    ["Colour by time", "Colours the points from oldest (blue) to newest (red) instead of one colour."],
    ["Time cursor and playback", "The slider runs over the From/To range. Moving it or pressing Play switches the cursor on: only positions up to the cursor time are shown. Every shown source gets its own current position (its last report at or before the cursor), marked by a pulsing dot in the source colour with the kind icon and labelled with the source, the report time and its age, and its own trail of the last n minutes. The transport buttons are previous point, play, pause, stop and next point: play advances the cursor by the chosen amount of data time per real second and stops at the end of the range, pause keeps the cursor where it is, stop switches the cursor off, and the step buttons jump to the previous or next report of any shown source inside the From/To range. Follow keeps the most recent of the current positions in view."],
    ["Timeline (View → Timeline)", "A panel below the map with one time axis over the From/To range and one lane per shown source (or the source chosen in its list), each named with its colour and icon. Stays are bars in the source colour, labelled with the place or address where there is room; the thin line runs from report to report; hatched areas are gaps without reports (at least " + gapMinutes + "); with \"All sources\", a vertical connector joins the two lanes of every encounter (band = its duration; dashed = joint movement), and an outline marks the time two sources stayed at a shared place together. The vertical line is the time cursor: a click sets it, the arrow keys step it from report to report (Home/End: range ends, Escape: off). Hovering or focusing shows every lane's state at that time. The timeline follows the time range and the shown sources, not the accuracy filter or the cursor. The time axis stays at the top of the panel while the lanes and the case place rows scroll under it (the arrow keys up and down, Page up and Page down scroll them from the keyboard), and each block carries its own heading, so six sources stay readable on a small screen. It is on at start when the map has two or more sources or case places, is always printed, and CSV exports its elements (derived, not recorded)."],
    ["Case places and position check", "For every case place and source: a visit is a run of consecutive reports inside the radius (great-circle distance to the centre, bound included); a report outside the radius or a silence of more than " + casePlaceGapMinutes + " ends the visit, and its first and last report are not an arrival or a departure. Radii of reports are uncertainty radii (see Accuracy level). A possible visit is a report outside the radius whose uncertainty radius reaches the radius, or a record of an excluded positioning method (see Positioning method) inside the radius or within the radius plus the larger of " + casePlaceMargin + " and its uncertainty radius; possible visits are counted apart and never merged with visits. With a time window (bounds included) each source gets exactly one verdict: present (at least one report inside the radius), possibly present (none inside, but at least one that could be), elsewhere (reports exist and every one lies farther away than the radius plus its uncertainty radius; the closest is given) or no reports in window: the source is silent, so nothing can be said about where the device was (this is not absence), and the nearest reports before and after the window are given. A verdict describes the records of a device, never a person. A verdict covers only the moments of the records: between records nothing is known, so the popup gives the first and last report of the window and the longest span of the window without a report (also before the first and after the last one); GEOSnap sets no threshold for them. When every report inside the radius during the window has an accuracy circle larger than the radius (a record without an accuracy value counts with the assumed " + casePlaceMargin + "), the verdict present says so and the best reported accuracy among these reports is given. Records without an accuracy value are never a possible visit, except records of an excluded positioning method inside the radius, and count as elsewhere only beyond the radius plus " + casePlaceMargin + " (the accuracy limit of the analysis, taken as its assumed accuracy); a nearer one makes the verdict possibly present with the basis \"accuracy not reported; within the assumed " + (casePlaceBlock.unknown_accuracy_margin_m === undefined ? maxAccuracy : casePlaceBlock.unknown_accuracy_margin_m + " m") + "\". Inside the radius such a record counts with the same assumed accuracy: when no report inside the radius during the window has an accuracy within the radius, the verdict present carries the basis \"inside the radius, but every such record has an accuracy circle larger than the radius or no accuracy value (assumed " + casePlaceMargin + ")\". Every record takes part, whatever its accuracy and whatever the map shows. When the radii as reported give another verdict or basis, the popup adds it as \"As reported: …\". The timeline has one row per case place: the window as a bracket, the visits of every shown source as bars in its colour (Enter or a double click shows the place on the map). Complete lists: case_places_<stamp>.csv and analysis.json (case_places, with gap_threshold_minutes and unknown_accuracy_margin_m)."],
    ["Matrix (View → Matrix)", "The presence matrix, computed at generation time; offered when the map has two or more sources or case places. Places are rows, the shown sources are columns, and a cell gives the visits of one source at one place: their number, the total dwell, the first and the last report. Rows: the shared places by total dwell (longest first), then the case places in the order entered, then the stay places of one source only by total dwell. The two kinds of rows are measured differently: at a shared place or stay place (stay centres grouped within the matrix tolerance of " + matrixTolerance + "; the Shared places layer and the timeline keep the stop radius of " + stopRadius + ") a visit is a stay of at least " + stopMinutes + "; at a case place a visit is a run of consecutive reports inside the radius entered by the examiner, so a single report is a visit of 0 minutes. Counts and dwell of the two kinds must not be compared with each other. \"simultaneous\" marks a place where visits of different shown sources overlap in time. A cell without a visit means that no visit of that source was found, not that the device was never at the place. Click a cell: the map flies to the place, its radius is marked (a click on the map clears it), the time cursor moves to the first report of the first visit (it stays inside the From/To range), and the visits are listed below the table, which scrolls by itself under its fixed head; the place is shown in the free part of the map, not under the window; click a visit to move the cursor there. Click a place name to show the place; a case place opens its popup. \"shared only\" keeps the places with visits of at least two shown sources. The Tolerance field regroups the stay centres in this browser at another distance (0 to 3000 m, same algorithm as the run; case places keep their radius); the window then names the run value that the report and the CSV use, and Reset returns to it. Rows with a simultaneous visit of two or more shown sources are highlighted and listed first, then every row by its total dwell over the shown sources. A hidden source loses its column, and places without a visit of a shown source are left out (case places stay). At most 200 rows are listed: every case place, then the shared places and the stay places with the longest dwell; presence_matrix_<stamp>.csv lists every place and every visit. The table is not printed."],
    ["Crystal ball", "Estimates where the device is likely to be at a reference time (default: now) from its own routine; it is an estimate, not evidence, and must be acknowledged once per page. \"Source\" chooses whose records it uses (shown sources; default the first). The reference time is read in the display zone (" + (payload.display_zone || "as generated") + ") with the clock changes recorded at generation: in a repeated hour it means the earlier occurrence unless only the later one lies after the last report, in a skipped hour the next valid time; elapsed times run on UTC, times of day on the wall clock. Basis: a presence timeline from the stays and gaps of the analysis (complete, independent of duplicate removal and thinning), with stays clustered into known places within " + stopRadius + ". Comparable days are days on which the device was at the place of the last report around the same time of day. Ranking ladder: S2 comparable days of the same day class (weekday/weekend, when at least 2 weekend days and 3 weekdays exist), S3 all comparable days, S4/S5 the routine at the reference time of day when fewer than 3 comparable days exist; each level is smoothed towards the next lower one with 3 pseudo-days. Samples count days, never reports: below 5 days only \"x of n days\", otherwise a percentage with a 95 % Wilson interval. Badge: weak below 5 days or on the routine levels (then no place is called most likely: search from the last known position first), medium from 5 days, strong from 14 days with at least 10 effective days on S2/S3. The window shows, top down: warnings; the headline with its badge; the last report and the reference time; one summary line with the search rings r50/r80/r95 and the tendency; the direction chart beside the top 3 places (click one to centre it); then collapsed sections: Ranking, Directions, Transitions, Stay & silence, Routes & destinations, Hazards, Other sources and Why?. Search rings: analog-day windows, one window of the elapsed length per comparable day starting at the place of the last report at the same time of day, reach from the rendered reports and the stays inside the window (away from a known place: windows starting near the last position; fallback: all windows). \"Of N comparable windows, 50 % stayed within r50 …\" (farthest distance plus the uncertainty radius of the last report, its accuracy at 95 %); with few windows r95 is the farthest reach seen so far (\"max. seen\"; about n of n+1 new days stay inside), and equal radii mean the farthest reach was the same distance, typically one destination. Tendency: the direction from the last position by the first tier with evidence, always named: departures from this place on comparable days, else windows starting near the last position, else the bearings of the other known places weighted by days visited (\"known places lie …\"). One direction per day; a Rayleigh test decides: established (p < 0.05, at least 5 effective days) gives a solid needle with a wedge showing how uncertain that direction is (95 % confidence of the mean direction; later positions often lie outside it), otherwise a faint dashed needle \"no preferred direction established … weak lean\", or with fewer than 3 days only the listed bearings; two opposite directions get two needles. The chart is a compass centred on the last position (directions only, not to map scale): day bearings as dots on the rim (size = day weight), the direction rose shaded underneath (area = share of leaving days; hover or focus a wedge for its days, share and 80 % reach), the last movement as a thin second needle and matching destinations as numbered squares; the Directions section lists the same as a table. The map shows the same tendency (orange) and, where at least 3 days left in a sector, the direction rose (teal wedges, length = 80 % reach). \"Routes from here\" (off by default) draws the earlier trips from this place bundled by destination, dashed where the device was silent, click to centre. While moving: matching destinations and a dashed extrapolation cone of the last movement (up to 30 min after the last report). Transitions, the stay duration, the silence block (how earlier gaps starting here ended; assumes the device stayed put while silent) and the motion line are not mixed into the ranking. Hazards names the nearest embedded hazard place within r95 and offers \"Check hazards in r95\" (see Check surroundings). Other sources lists each other shown source's report nearest to the chosen source's last report (within ± " + encounterMinutes + "), else its latest earlier one, with distance and bearing. Clicking a day in \"Why?\" moves the time cursor there. Recording: \"Record search area\" works only when the map was opened through GEOSnap (summary screen, key O) in the running GEOSnap session; the local GEOSnap server validates the record (source with its SHA-256, reference time, last position with its uncertainty radius, rings with basis and n, rose, cone, candidates, nearest hazard, confidence, warnings, model parameters including the accuracy level settings and the excluded positioning methods) and itself writes search_areas/search_area_<n>_<stamp> as JSON, GPX, KML and a one-page A4 search area sheet (HTML, print to PDF), appending their SHA-256 to search_areas/records.jsonl, a hash chain that GEOSnap --verify checks. The window then shows the file names with short hashes and the SHA-256 of the last line of records.jsonl with a copy button: note it in the case file, it anchors the hash chain. \"Download (not recorded)\" saves the same record as a _derived JSON file, neither recorded nor hashed. Everything else stays in this browser; the estimate is named in the print header and exports while shown. Validation: backtested on public GPS logger tracks of 49 people (GeoLife, 2007–2012) and one sparse phone export. A medium or strong basis named the right place in about 65–85 % of cases one hour ahead and 40–60 % twelve hours ahead; on a weak basis \"still at the last position\" was right more often for the first hour; stated percentages above 80 % held about 8 in 10; the 95 % ring held 86–93 %. Phone location histories were not available for validation."],
    ["Check surroundings (Places window)", "Lists the places of the ticked categories around a centre, sorted by distance, with symbol, category, name, distance, direction and origin; above the list the nearest hit and the count per category (\"nearest Water: 180 m NW\"). Click a line or row to centre the map. Centres come from the popup of a point, a stay, a last known position, an encounter, a saved place, a crystal ball candidate or a crystal ball ring label (click it): the check takes that centre and its own extent (uncertainty radius, see Accuracy level; stop radius; ring radius), at least " + (online.overpass_radius_m || 250) + " m, changeable in the Radius field; \"Check a point on the map…\" takes the next map click. Profiles preselect categories (Hazards: water, railway line, bridge, hazard site, forest, park; Shelter and help: police, hospital, social facility, camp/shelter, lodging, place of worship; Onward travel: railway station, transport stop, fuel station, airport/harbour, parking; Recorded traces: surveillance camera, bank/ATM, supermarket, fuel station, pharmacy); the ticks stay changeable, and a selection matching no profile reads Custom. Offline first: a check is answered from the embedded places (\"answered from embedded data\", no network) when the checked circle lies completely inside one of the circles of " + (online.overpass_radius_m || 250) + " m queried at generation and every ticked category was queried then. The map stores the centres of those circles as the generation chose them (per source the last known position, then the stays by duration, sources in turn, a candidate closer than half the radius to a chosen one dropped, at most 10); they count only when the map holds at least one embedded place (otherwise the generation query failed or found nothing). Offline answers measure to the feature centre: areas and lines whose centre lies outside the circle but within " + (online.overpass_radius_m || 250) + " m of it are listed as \"centre outside; edge may be closer\". Otherwise Overpass is asked live from this browser (not recorded; the Overpass operator receives the centre and radius, or the simplified route and corridor width), with the density rule of the Places section and a time limit; embedded and live hits are merged by OSM type and id, so an embedded place keeps the origin \"embedded\". \"Check along the shown route\" checks a corridor (default 100 m, at most 500 m) along the shown route of one source: the route is simplified to at most 100 vertices for the Overpass linestring filter (around with a coordinate list); distances use every shown report, and the list can be sorted by the time the nearest report passed (\"passed 14:32\"). CSV and GeoJSON export the list with centre, radius, profile, query time, endpoint and \"not recorded\" as _derived files. Live checks and the Referer: overpass-api.de answers a browser request only when it carries a Referer (the address of the page). A map opened directly from disk (file://) never sends one. " + fallbackSentence + " Open the map from GEOSnap instead (summary screen, key O: the map is served on http://127.0.0.1, the browser sends a Referer and the primary server is used), or set online.overpass_browser_endpoint in config.toml to an instance without that requirement and generate the map again. A busy server (HTTP 504 or 429) is asked once more after 8 s. Limits: OpenStreetMap data are incomplete (absence is no proof), live results are a view, not evidence, and the public Overpass instance limits usage."],
    ["Neighbours", "Clicking a point highlights the previous and next point of the same source that the map shows (filters and thinning decide which those are) with the geodesic distance, the time difference, the speed and its interval; a new render or source choice clears it."],
    ["Briefing", "The list of sources, then one collapsible section per shown source (last known position, stays, gaps, key figures, saved places; \"Points analysed\" gives those beyond the accuracy limit and those left out by positioning method, which add up to the total), the encounters and shared places tables when present (click a row to centre the map) and the provenance with the file name and SHA-256 hash of every source."],
    ["Exports (PNG, CSV, GeoJSON, GPX)", "Cover the currently shown positions of the shown sources; CSV and GeoJSON carry the source id and name, the record name and description and whether the accuracy was reported; GPX writes one track per source. PNG, GeoJSON and GPX name the filters in force (time range, accuracy limit, time cursor, sources). Their file names carry _derived: they are not part of the recorded evidence and are neither hashed nor logged."],
    ["Accuracy level", "A reported accuracy is a confidence radius, not a guaranteed bound: many devices report the radius within which the true position lies with about 68 % probability, some the 95 % radius. The level is chosen per source in the project setup (68 %, 95 % or unknown) and shown in the Briefing. With analysis.accuracy_confidence = p95 (" + (parameters.accuracy_confidence === undefined ? "the default" : "this map: " + parameters.accuracy_confidence) + ") the analysis uses the radius at 95 %: a 68 % radius is multiplied by " + accuracyScaleFactor.toFixed(2) + ", the Rayleigh factor from the 68 % to the 95 % radius of a circular normal error (sqrt(ln 0.05 / ln 0.32) = " + accuracyScaleFactor.toFixed(4) + "); a source of unknown level is treated as 68 %, the cautious choice; a 95 % radius stays as it is. With \"reported\" every radius is used as reported. This uncertainty radius drives every bound and margin: speed intervals and the stationary class, the minimums of the Speed tool, possible visits, \"elsewhere\" and the basis of \"present\" at case places, the widening of encounters, the thresholds of the crystal ball and the extent of Check surroundings from a point or a last known position. A larger radius weakens lower bounds and \"elsewhere\" and widens what is only possible; claims resting on fixed distances do not change. The reported radius stays what is shown and exported: tooltips give both figures, accuracy circles and the accuracy filter use the reported radius. Where numbers are shown, the figure as reported stands beside the one at 95 % (Speed tool, speed intervals); a case place shows its verdict as reported only when it differs."],
    ["Positioning method", "When the source names how a position was found (a CSV column such as source, provider or fix; Google source; GeoJSON property; GPX fix), each record carries gnss, wifi, cell or network, shown in its tooltip as \"Positioning\"; unknown values are kept in the record's description. Records of the methods in analysis.excluded_positioning_methods (" + ((parameters.excluded_positioning_methods || []).length ? "this map: " + parameters.excluded_positioning_methods.join(", ") : "none on this map") + "; by default cell, whose radius is often a sector size rather than an accuracy) are left out of speed, stays and encounters: their tooltip says so, they have no speed and cannot end a Speed tool range. They stay on the map, in the exports and in the case places (as possibilities), and gaps still count them, since such a record shows the device reported. The Briefing gives the records per method for each source and how many were left out, and names newer records left out after the last known position."],
    ["Stay arrival and departure", "The first and last record of a stay are not the arrival and the departure: the device may have arrived earlier and left later. The analysed record before the stay bounds the arrival when it shows the device elsewhere: it reports an accuracy, lies farther from the stay centre than the stop radius plus its uncertainty radius, and the step to the stay takes time and stays below " + implausibleSpeed + ". The device then arrived between that record and the first one of the stay; the record after the stay bounds the departure likewise. Such a bound may span a silence. Otherwise that side is not bounded: when the neighbouring record could lie at the place (within the stop radius plus its uncertainty radius), reports no accuracy, is a position jump or shares the instant of the stay record, or when there is none: the device may already have been there, or stayed on. When the local time of the first record of the stay or of the record after it occurred twice (clocks going back), the arrival or departure bound lies later by that much. Stay tooltips and the timeline give both; the timeline adds the date when a bound falls on another day."],
    ["Encounter time offset", "An encounter pairs reports of two sources within " + encounterMinutes + " of each other, so the two devices were not necessarily there at the same moment. \"smallest time offset 40 s (closest pair 2 min 5 s)\": the smallest time difference of any coinciding pair of reports and the time difference of the pair that came closest in place (of equally close pairs, the one nearest in time), both rounded down to whole seconds. Both are differences of the recorded times; when a local time of a report occurred twice (clocks going back), the text says by how much it may lie later. Shown in the encounter tooltip, the timeline, the Briefing and the GPX and KML descriptions; the CSV, analysis.json and the report keep the precise values."],
    ["Accuracy not reported", "Records without an accuracy value (KML, GPX, and CSV or Google records that lack one) read \"Accuracy: not reported\" in tooltips, the Briefing and the crystal ball and get no accuracy circle; their accuracy is stored as 0 m, so they pass the accuracy filter and the analysis accuracy limit. Each record is judged by itself: in a CSV or Google source the records with an accuracy keep their ± value. The Sources window and the legend say per source \"accuracy not reported\" (no record has one) or \"accuracy partly reported\" (some records lack one)."],
    ["Point tooltips", "Hover a point: source, the record's name, its description, the original record (shortened), position with accuracy (with the 95 % radius beside it when the analysis scales it: \"± 20 m (95 %: 32 m)\"), the positioning method when the source names it, UTC and local time, the record number and the reports at that position. The description is what the file says about the record: prose (a KML description, a GPX comment) stays as it was; a field with a name (a CSV column without a role, a KML ExtendedData field, a GeoJSON property, GPX hdop, a Google source or deviceTag) is shown as its own \"name: value\" row; rows labelled GEOSnap are written by GEOSnap itself (a coordinate conversion, an ambiguous local time, a MultiPoint index), everything else comes from the file. Text records (.txt/.log) carry no name or description. Long values wrap inside the tooltip, and a tall tooltip scrolls: it opens at the pointer and stays there, so the pointer can move onto it and the wheel scrolls it without zooming the map; it closes shortly after the pointer left it, and its text can be selected. The original record is shortened only beyond 1000 characters and then gives its full length; the full record stays in the source file and in points_<stamp>.csv (record_note)."],
    ["KML sources", "KML exports (mobile forensic tools, Google Earth): one point per placemark with a time, with its name and description; the fields of an ExtendedData block (Data name/value, SchemaData SimpleData) follow the description as \"name: value\" rows, shortened when long. Record numbers count placemarks. KML carries no accuracy. Placemarks without a time are listed as saved places."],
    ["GPX sources", "GPX 1.0/1.1 track points, route points and waypoints with a time become points (name and description or comment shown; record numbers count GPX points). GPX carries no accuracy in metres: hdop is a dilution factor and appears only in the description (\"hdop: 1.4\"). Points without a time are listed as saved places; times without a zone are read as UTC."],
    ["CSV sources", "Tables with a column mapping chosen in GEOSnap (Columns…): latitude, longitude and timestamp, optionally a separate time of day, accuracy in metres, name and description, or one column holding the whole position. Coordinates are read per cell: decimal degrees, degrees with minutes and seconds, hemisphere letters, UTM, MGRS, WKT points and geo URIs may be mixed; whatever was not a plain decimal number is named in the tooltip's description together with the text that was read (\"[GEOSnap] coordinates read as ... from ...\"; parts starting with [GEOSnap] are written by GEOSnap, everything else comes from the file), and an MGRS position is the south-west corner of its square. A position column has one order (latitude first or longitude first), recorded with the mapping. The description also lists every other non-empty column of the row as \"header: value\" (shortened when long; the original row is kept). Record numbers count lines of the file. Times without an offset are read in the zone chosen at setup; the order of day and month in dates like 03/04/2026 is one choice per file and separator mark (. / -), recorded with the mapping. Rows without an accuracy value (no accuracy column mapped, or an empty cell) read \"Accuracy: not reported\"; the mapping is recorded in metadata.json and the report."],
    ["GeoJSON sources", "GeoJSON (RFC 7946, .geojson or .json): a FeatureCollection read feature by feature, or a single Feature. Point features become points, a MultiPoint one point per position (\"[GEOSnap] MultiPoint 2 of 5\" in the description); lines, polygons and features without geometry are not imported. Coordinates are longitude, latitude by definition of the format. The timestamp comes from the one property named like a time (time, timestamp, date, datetime, zeit, zeitstempel, ..., or a date property with a separate time of day); a feature with several such properties is rejected naming them, one without any is listed as a saved place. Times without an offset are read in the display zone of the run (metadata.json says which) and rejected when the display zone is local. Accuracy (accuracy, radius, genauigkeit, ...) and name (name, title, label, ...) come from the properties so named; every other property is shown as \"name: value\" (nested objects as dotted paths, arrays as JSON text, shortened when long). Record numbers count features; the original record is the feature as compact JSON."],
    ["Google Takeout sources", "Records.json (location history), the on-device Timeline.json export and Semantic Location History: every timed position becomes a point, record numbers count records of the file. Accuracy is shown where Google gives one (accuracy, accuracyMeters); records without it read \"Accuracy: not reported\". Visits and activities are Google's own inference: their points say \"(provider inference)\" in the description and are never GEOSnap stays by themselves. Frequent places of the Timeline export are listed as saved places."],
    ["Print", "Prints the map with a header naming the project, every source with its file and hash, generation time, base map, time zone and the filters in force; tiles print only when already loaded."],
    ["Map style", "Switches the base map between the built-in providers (online maps), the local tiles (local maps) or no base map. This is a view choice made in the browser and is not recorded; the base map at generation is documented in metadata.json."],
    ["Windows", "Drag a window by its title bar to move it; it stays inside the map, and the window you grab comes to the front. The title bar stays at the top while the window scrolls, so fold and close are always in reach. Positions last until the page is closed. The layer control and the legend stay in their corners."],
    ["View", "Shows or hides the legend (off at start), the layer control, the Places window, the Sources window, the timeline and the Matrix window without changing which layers are on. The Timeline and Matrix ticks keep their place and are disabled with a reason when the records do not carry what they need. The chevron in the title bar of every window, the legend and the layer control folds it to its title bar and back (not kept after reloading)."]
  ];

  var element = G.element;

  function definitionList(rows) {
    var list = element("dl");
    rows.forEach(function (row) {
      list.appendChild(element("dt", row[0]));
      list.appendChild(element("dd", row[1]));
    });
    return list;
  }

  function tagRulesText(rules) {
    return rules.map(function (rule) { return rule[0] + "=" + rule[1].join("|"); }).join(", ");
  }

  // Density classes and their radius caps, read from the catalogue itself (e.g. "dense up to 2000 m").
  function densityRuleSentence() {
    var capByDensity = {};
    G.PLACE_CATEGORY_ORDER.forEach(function (category) {
      var entry = G.PLACE_STYLES[category];
      capByDensity[entry.density] = entry.max_radius_m;
    });
    var caps = Object.keys(capByDensity).sort(function (a, b) { return capByDensity[b] - capByDensity[a]; })
      .map(function (density) { return density + " up to " + capByDensity[density] + " m"; }).join(", ");
    return "Each category has a density class that caps the search radius (" + (caps || "no catalogue in this map") + "): a category whose cap is below the chosen radius (or corridor width) is skipped in a live check and named in the status line. Hits marked \"large feature, centre outside search radius\" are big areas or lines whose centre lies more than three times the radius away.";
  }

  // Groups → categories with their OSM tags, in catalogue order; queried categories are marked.
  function catalogueList() {
    var list = element("dl");
    var queried = online.overpass_categories || [];
    G.PLACE_GROUPS.forEach(function (group) {
      list.appendChild(element("dt", group.name));
      var categories = element("ul");
      group.categories.forEach(function (category) {
        var entry = G.PLACE_STYLES[category];
        categories.appendChild(element("li", entry.emoji + " " + entry.label + ": " + tagRulesText(entry.rules) + " (" + entry.density + (queried.indexOf(category) >= 0 ? ", queried at generation)" : ")")));
      });
      var description = element("dd");
      description.appendChild(categories);
      list.appendChild(description);
    });
    return list;
  }

  function buildHelp(container) {
    container.textContent = "";
    container.appendChild(element("h3", "Layers (layer control, top right)"));
    container.appendChild(definitionList(G.overlays.map(function (entry) {
      return [entry.name, layerHelp(entry.name)];
    })));

    container.appendChild(element("h3", "Places"));
    var queriedCategories = (online.overpass_categories || []).filter(function (category) { return G.PLACE_STYLES[category]; });
    var placesIntro = !online.enabled
      ? "Online services were disabled when this map was generated, so no Overpass query was made for this map: the Places window lists no embedded places, and live checks are unavailable."
      : queriedCategories.length === 0
        ? "Online services were enabled when this map was generated, but no place categories were configured, so no Overpass query was made for this map; \"Check surroundings\" asks Overpass live."
        : "Embedded places were queried from Overpass when the map was generated around the last known position and the stays, within " + (online.overpass_radius_m || "the configured") + " m; when the query succeeded they are documented in overpass_<stamp>.json. \"Check surroundings\" answers from them when it can and otherwise queries Overpass from this browser; live results are not recorded. The ticked categories in the Places window apply to both.";
    container.appendChild(element("p", placesIntro));
    container.appendChild(element("p", queriedCategories.length
      ? "Queried at generation: " + queriedCategories.map(function (category) { return G.PLACE_STYLES[category].label; }).join(", ") + ". Other categories were not queried in this project and are answered only by a live check."
      : "No category was queried at generation in this project."));
    var skippedCategories = (online.overpass_skipped_categories || []).filter(function (category) { return G.PLACE_STYLES[category]; });
    if (skippedCategories.length) {
      container.appendChild(element("p", "Configured but skipped at generation because the radius of " + online.overpass_radius_m + " m exceeds their density limit: " +
        skippedCategories.map(function (category) { return G.PLACE_STYLES[category].label; }).join(", ") + "."));
    }
    container.appendChild(element("p", densityRuleSentence()));
    container.appendChild(catalogueList());

    container.appendChild(element("h3", "Tools"));
    container.appendChild(definitionList(TOOL_HELP));

    container.appendChild(element("h3", "Map styles"));
    container.appendChild(definitionList((payload.tile_providers || []).map(function (provider) {
      return [provider.label, provider.policy_note + " Tile requests disclose the viewer's IP address and the viewed area to " + provider.origins.join(", ") + "."];
    }).concat([["No base map", "Positions on a plain background with the graticule; nothing is loaded from the internet."]])));
  }

  var helpWindow = document.getElementById("help-window");
  var content = document.getElementById("help-content");
  document.getElementById("help-button").addEventListener("click", function () {
    if (helpWindow.hidden) {
      buildHelp(content);
      G.setWindowCollapsed(helpWindow, false);
      G.closeCrystalBall();
    }
    helpWindow.hidden = !helpWindow.hidden;
  });
  document.getElementById("help-close").addEventListener("click", function () { helpWindow.hidden = true; });
})();
